import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.D1z9wg1y.js";const g=JSON.parse('{"title":"The harness command","description":"","frontmatter":{},"headers":[],"relativePath":"harness-command.md","filePath":"harness-command.md"}'),i={name:"harness-command.md"};function n(d,e,l,h,r,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="the-harness-command" tabindex="-1">The <code>harness</code> command <a class="header-anchor" href="#the-harness-command" aria-label="Permalink to &quot;The `harness` command&quot;">​</a></h1><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness [--profile F] [--models F] &lt;subcommand&gt; [options] [arguments]</span></span>\n<span class="line"><span>harness --help</span></span>\n<span class="line"><span>harness &lt;subcommand&gt; --help</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>bin/harness</code> is the entry point of the harness. It needs Python 3.14 or later and nothing beyond the standard library. Put <code>bin/</code> on the <code>PATH</code>, as the step <em>The clone</em> of <a href="./setup-macos#the-clone">setup-macos.md</a> and <a href="./setup-linux#the-clone">setup-linux.md</a> shows. An older Python prints the version that it found and the version that it needs, and exits 2. Every subcommand runs on the interpreter of the Python environment of the harness, which <code>bin/harness</code> makes with <a href="./dependencies#uv">uv</a> the first time that it runs outside a session.</p><p>Each subcommand of <code>harness</code>, such as <code>install</code> or <code>doctor</code>, keeps one contract:</p><ul><li><strong>A subcommand that changes something is dry by default.</strong> It prints its plan, and exits 1 when something would change, 0 when nothing would. <code>--apply</code> makes the change, and exits 0.</li><li><strong>A read-only subcommand takes no mode flag.</strong> It exits 0, or 1 where its section says so.</li><li><strong>Exit 2 is a usage error or a failure</strong>, with one line on standard error: <code>harness &lt;subcommand&gt;: &lt;reason&gt;</code>.</li></ul><p>So a dry run in a script tells you whether there is work to do: exit 1 means &quot;run it again with <code>--apply</code>&quot;. <a href="#setup"><code>setup</code></a> is the one exception: it has no <code>--apply</code>, because its y/N in a terminal, or <code>--yes</code> in a script, is the confirmation, and <code>--dry-run</code> prints its plan. The two checks differ: <code>harness test</code> exits 1 when a test case fails, and <code>harness doctor</code> exits 1 when a check fails.</p><p><a href="./development">development.md</a> describes the cases of <code>harness test</code>, and <a href="./architecture">architecture.md</a> the Claude Code layer that <code>harness install</code> writes.</p><h2 id="global-options" tabindex="-1">Global options <a class="header-anchor" href="#global-options" aria-label="Permalink to &quot;Global options&quot;">​</a></h2><p>These options come before the subcommand.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--profile F</code></td><td style="text-align:left;">the private profile. If it is not given, the profile is <code>$RESEARCH_HARNESS_PROFILE</code>, or <code>~/.config/research-harness/profile.toml</code> if that is not set. <code>examples/profile.toml</code> shows every key</td></tr><tr><td style="text-align:left;"><code>--models F</code></td><td style="text-align:left;">the model tables. They map each model tier to its model in each frontend, which is a tier of Antigravity&#39;s own in Antigravity, and an agent to its own model. If the option is not given, the model tables are <code>$RESEARCH_HARNESS_MODELS</code>, or <code>models.toml</code> beside the profile if that is not set. <code>examples/models.toml</code> shows the layout</td></tr><tr><td style="text-align:left;"><code>-h</code>, <code>--help</code></td><td style="text-align:left;">print the list of subcommands. <code>harness &lt;subcommand&gt; --help</code> prints the options of one subcommand</td></tr></tbody></table><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">subcommand</th><th style="text-align:left;">does</th><th style="text-align:left;">changes something</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#setup"><code>setup</code></a></td><td style="text-align:left;">installs the tools and frontends that the profile&#39;s <code>[setup]</code> chooses, then runs <code>install --apply</code>, <code>trust --apply</code>, the jobs and <code>doctor</code></td><td style="text-align:left;">yes, after y/N or with <code>--yes</code></td></tr><tr><td style="text-align:left;"><a href="#install"><code>install</code></a></td><td style="text-align:left;">installs the Julia environment of the scripts, syncs the Python environment of the harness, and installs the Claude Code layer with the sections <code>permissions</code>, <code>hooks</code>, <code>sandbox</code> and <code>modelSettings</code> of <code>settings.json</code>, the OpenCode configuration, the oh-my-pi permission layer, instructions, rules, agents, models and MCP entry, and the Antigravity guard hook, permission rules, instructions, rules, skills, agents and MCP entry</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#update"><code>update</code></a></td><td style="text-align:left;">brings the harness checkout up to <code>origin/main</code>, then runs <code>install --apply</code>. It does not move a checkout that is pinned to a commit</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#doctor"><code>doctor</code></a></td><td style="text-align:left;">checks the setup of this machine: the tools, the profile, the install and the jobs</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#trust"><code>trust</code></a></td><td style="text-align:left;">sets Claude Code workspace trust for every repository of the tree</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#dotfiles-kit"><code>dotfiles-kit</code></a></td><td style="text-align:left;">copies the dotfiles kit of the harness into a chezmoi source</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#clone"><code>clone</code></a></td><td style="text-align:left;">clones each repository of the repository table that has no directory yet</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#repos-status"><code>repos status</code></a></td><td style="text-align:left;">reports each repository: its branch, its commits ahead and behind, its changed files and its open pull requests</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#repos-pull"><code>repos pull</code></a></td><td style="text-align:left;">fast-forwards each repository that is behind its upstream</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#repos-push"><code>repos push</code></a></td><td style="text-align:left;">pushes each repository that is ahead of its upstream, one at a time</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#repos-sync"><code>repos sync</code></a></td><td style="text-align:left;"><code>repos pull</code>, then <code>repos push</code></td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#githooks"><code>githooks</code></a></td><td style="text-align:left;">installs the shared git hooks into every package and experiment</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#wiki-lint"><code>wiki-lint</code></a></td><td style="text-align:left;">lints the Markdown of the prose repositories: links, paths, line citations, frontmatter</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#wiki-lint-hook"><code>wiki-lint-hook</code></a></td><td style="text-align:left;">installs the wiki-lint hook into the prose repositories</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#workflows"><code>workflows</code></a></td><td style="text-align:left;">installs the canonical GitHub workflows into every package and experiment</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#ci-protection"><code>ci-protection</code></a></td><td style="text-align:left;">protects every default branch on GitHub with a ruleset</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#format"><code>format</code></a></td><td style="text-align:left;">runs JuliaFormatter over every tracked <code>.jl</code> file of the packages and experiments</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#render"><code>render</code></a></td><td style="text-align:left;">prints a template rendered with the profile</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#get"><code>get</code></a></td><td style="text-align:left;">prints a profile value</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#leaks"><code>leaks</code></a></td><td style="text-align:left;">searches the repository for the private strings of the profile</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#settings"><code>settings</code></a></td><td style="text-align:left;">measures and checks the Claude Code settings: <code>surface</code>, <code>compare</code>, <code>twins</code>, <code>selftest</code></td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#permissions"><code>permissions</code></a></td><td style="text-align:left;">generates the OpenCode permission block and path-guard list from the settings template</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#test"><code>test</code></a></td><td style="text-align:left;">runs the harness&#39;s own test cases</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#mutate"><code>mutate</code></a></td><td style="text-align:left;">runs named mutants of the Python code against the parts of <code>test</code> that should kill them</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;"><a href="#changelog"><code>changelog</code></a></td><td style="text-align:left;">joins the changelog fragments of <code>changelog.d/</code> into <code>CHANGELOG.md</code>, or checks that a branch adds one</td><td style="text-align:left;">yes</td></tr><tr><td style="text-align:left;"><a href="#skill-triggers"><code>skill-triggers</code></a></td><td style="text-align:left;">tests whether each skill loads on its queries</td><td style="text-align:left;">runs paid sessions with <code>--apply</code></td></tr></tbody></table><p>The sections below give each subcommand&#39;s synopsis, what it does, its options, its exit status, the files that it reads and writes, where to run it, and examples. <em>Where to run it</em> says whether an agent session can run the subcommand. A session runs in the Claude Code sandbox, which refuses some writes and some network calls; a subcommand that needs them runs in your own terminal.</p><h2 id="set-up-and-keep-a-machine" tabindex="-1">Set up and keep a machine <a class="header-anchor" href="#set-up-and-keep-a-machine" aria-label="Permalink to &quot;Set up and keep a machine&quot;">​</a></h2><h3 id="setup" tabindex="-1"><code>setup</code> <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;`setup`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness setup [--yes] [--dry-run]</span></span></code></pre></div><p>Sets up a machine in one run: the tools and the frontends that the profile&#39;s <a href="./profile#the-setup-table"><code>[setup]</code></a> chooses, then the harness&#39;s own steps. The machine needs Python 3.14, uv, git and the clone before it, and on macOS Homebrew. It runs on macOS and on Ubuntu, on the architectures <code>arm64</code> and <code>x86_64</code> of macOS and <code>x86_64</code> and <code>aarch64</code> of Linux.</p><p>In a terminal, <code>setup</code> asks its questions. Without a profile, it copies <code>examples/profile.toml</code> and asks only for the keys that have no default, <code>memory_project</code>, <code>tree_agents</code>, <code>org</code>, <code>repository_roots</code> and <code>leak</code>; an empty answer keeps the example&#39;s value. It then asks for the frontends and the components, each from a numbered list, and whether this machine develops the harness (<code>develop</code>), y/N. It shows the plan and runs it after y/N. The plan&#39;s first step writes the answers into <code>[setup]</code> of the profile. A missing <code>models.toml</code> beside the profile is copied from <code>examples/models.toml</code>.</p><p>The plan holds these steps, in this order:</p><ol><li>the directories that <code>install</code> needs: the tree instructions, each <code>repository_roots</code> entry, and with <code>opencode</code> the OpenCode configuration directory;</li><li>the packages. On macOS, one <code>brew install</code> line of the missing tools and of the tools below their minimum that Homebrew does not list as installed, one <code>brew upgrade</code> line of the tools below their minimum that it lists, and <code>brew install --cask iterm2</code>. On Ubuntu, one <code>sudo apt-get install -y</code> line of each package whose apt candidate meets the tool&#39;s minimum;</li><li>on Ubuntu, each tool that apt does not meet, from its pinned release of <code>setup/tools.toml</code> into <code>~/.local/bin</code>, after a check of the sha256 of the archive;</li><li>the vendor installers, in this order: juliaup, Julia through juliaup when juliaup is there (<code>juliaup update</code> when Julia is below its minimum), fatou on Ubuntu, Kaimon as a Julia app, Claude Code, and on Ubuntu OpenCode (with <code>--no-modify-path</code>) and oh-my-pi;</li><li><code>harness install --apply</code>;</li><li><code>git config core.hooksPath .githooks</code> in the clone;</li><li><code>harness trust --apply</code>;</li><li>with the component <code>jobs</code>, the jobs as the dotfiles kit&#39;s services step does them: the copies in <code>~/.local/bin</code>, then the launch agents or the <code>systemd --user</code> units, rendered with <code>harness render</code> and loaded;</li><li>with the component <code>julia</code>, the Kaimon token <code>~/.config/kaimon/auth-token</code>, mode 600, from the first key of <code>~/.config/kaimon/config.json</code> when that file exists and the token does not;</li><li><code>harness doctor</code>, after the lines under <em>By hand</em>, so that its report ends the run.</li></ol><p>A tool that is installed at or above its minimum of <a href="./dependencies">dependencies.md</a> is skipped; a tool with no minimum, only a version that it is tested with, is met by any version. After a Homebrew line or <code>juliaup update</code> for a tool below its minimum, <code>setup</code> reads the tool&#39;s version again. When it is still below, the step fails: for Julia, whose <code>juliaup update</code> keeps the default channel, with the line <code>juliaup add release &amp;&amp; juliaup default release</code>; for another tool, with the path of the copy that comes first on the <code>PATH</code>. <code>setup/tools.toml</code> holds the minimums and the pinned releases. The OpenCode installer runs only when <code>opencode</code> is not on the <code>PATH</code>, and the juliaup installer only when <code>juliaup</code> is not. <code>setup</code> runs the OpenCode installer with <code>--no-modify-path</code> and prints the <code>PATH</code> line of <code>~/.opencode/bin</code> instead; the juliaup installer adds its own <code>PATH</code> block to the shell startup files. Each step that <code>setup</code> cannot do, such as the Antigravity app and <code>loginctl enable-linger</code> for the jobs on Linux, is printed under <em>By hand</em>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--yes</code></td><td style="text-align:left;">read <code>[setup]</code> of the profile, or the defaults of a profile without it, and ask nothing. It never writes the profile</td></tr><tr><td style="text-align:left;"><code>--dry-run</code></td><td style="text-align:left;">print every command of the plan and change nothing, not even the profile</td></tr></tbody></table><p><strong>Exit status:</strong> 0 after the plan ran and <code>harness doctor</code> passed, after the dry run, and when the answer to the plan is no; 1 after the plan ran and <code>harness doctor</code> reported a FAIL; 2 when a step fails, which prints its output first, <code>harness doctor</code> with a status other than 0 or 1 included; when stdin is no terminal and <code>--yes</code> is not given; when <code>--yes</code> finds no profile; when <code>[setup]</code> cannot be written into the profile in place, naming the table to write; when an answer is not valid UTF-8; on Ubuntu when <code>apt-cache</code> fails, and without <code>sudo</code>, or when <code>sudo -n true</code> is refused, after the apt line is printed for an administrator; and on a system other than macOS and Ubuntu, or an unknown architecture. A second run plans again and starts from the first step; each step skips what is done.</p><p><strong>Reads:</strong> the profile, <code>setup/tools.toml</code>, the versions of the installed tools, and on Ubuntu <code>apt-cache policy</code>. <strong>Writes:</strong> the profile (in a terminal), <code>models.toml</code> when it is missing, the packages and programs that the steps install, and what <code>install</code>, <code>trust</code> and the jobs write.</p><p><strong>Where to run it:</strong> in your own terminal. A session runs only <code>--dry-run</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the plan for [setup], with no question</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # ask, show the plan, run it after y/N</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # the dotfiles kit&#39;s harness step</span></span></code></pre></div><h3 id="install" tabindex="-1"><code>install</code> <a class="header-anchor" href="#install" aria-label="Permalink to &quot;`install`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness install [--apply] [--force]</span></span></code></pre></div><p>Installs the Julia environment of the scripts, syncs the Python environment of the harness, and installs the configuration of each frontend that the profile&#39;s <a href="./profile#the-setup-table"><code>[setup]</code></a> chooses: Claude Code, OpenCode, oh-my-pi and Antigravity. Without <code>[setup]</code>, it installs all four and the Julia environment; with it, the Julia environment only with the <code>julia</code> component, and the Python environment always. A layer of a frontend that <code>[setup]</code> does not choose is neither planned nor removed. The installed configuration is not writable from a session, so the sources live in the harness repository, and <code>install</code> copies them into place. It plans every chosen frontend first and writes nothing while it plans. So a refusal stops the install before the first write. After <code>--apply</code>, it prints the restart line of each frontend whose files changed.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">install; without it, print the plan</td></tr><tr><td style="text-align:left;"><code>--force</code></td><td style="text-align:left;">replace a file that the plan refuses to replace; the refusal names the file</td></tr></tbody></table><p><strong>Exit status:</strong> 0 when nothing would change or <code>--apply</code> installed; 1 when the dry run has a change; 2 when a plan refuses, or the profile or the model tables do not load.</p><p><strong>Reads:</strong> the profile, the model tables, <code>providers.toml</code> and <code>network.toml</code> beside the profile, the tree instructions (<code>tree_agents</code> of the profile), and the sources of the harness checkout. <strong>Writes:</strong> for each chosen frontend, below <code>~/.claude/</code>, the OpenCode configuration directory, the oh-my-pi directory, and <code>~/.gemini/</code> when Antigravity has made it; the Julia environment with the <code>julia</code> component (see <a href="#the-julia-environment">The Julia environment</a>); and the Python environment (<code>~/.local/share/research-harness/python/</code>, with the <code>dev</code> group when <code>[setup]</code> of the profile sets <code>develop = true</code>). With <code>claude</code> chosen, it writes the stamp <code>~/.claude/.harness-install.json</code>, which the drift warning at session start reads.</p><p><strong>Where to run it:</strong> in your own terminal. A session cannot write the installed files.</p><p><code>install</code> warns when its checkout is behind its <code>origin/main</code>, as the last fetch saw it. It fetches nothing, and it installs the checkout as it is. To fetch, merge and install in one step, use <code>update</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # the plan</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # install</span></span></code></pre></div><h3 id="update" tabindex="-1"><code>update</code> <a class="header-anchor" href="#update" aria-label="Permalink to &quot;`update`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness update [--apply]</span></span></code></pre></div><p>Brings the harness checkout up to <code>origin/main</code>, and installs it. It works on the checkout that runs it, and only when its branch is <code>main</code> with the upstream <code>origin/main</code>: a development checkout. The dry run fetches, prints the new commits and the files that they change, and exits 1 when there is a new commit. <code>--apply</code> also shows the whole diff, through git&#39;s pager, and asks <code>y/N</code>. On <code>y</code> it merges <code>--ff-only</code> and runs <code>harness install --apply</code> from the merged checkout. Any other answer merges and installs nothing.</p><p>A checkout at a detached HEAD is pinned to a commit, for example by the dotfiles of a machine. Only a reviewed change of the pin moves it, so <code>update</code> stops there and moves nothing.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">show the diff, ask, merge and install</td></tr></tbody></table><p><strong>Exit status:</strong> 0 when the checkout is up to date, or after <code>--apply</code>; 1 when the dry run finds a new commit; 2 when the checkout is pinned, is on another branch, tracks another upstream, has commits that <code>origin/main</code> lacks, cannot fetch, has changes to tracked files (<code>--apply</code>), or has no terminal for the question (<code>--apply</code>), and when <code>install --apply</code> fails after the merge.</p><p><strong>Where to run it:</strong> in your own terminal. <code>--apply</code> asks a question, and the install writes files that a session cannot write.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # fetch and list the new commits</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # read the diff, answer y, merge and install</span></span></code></pre></div><h3 id="doctor" tabindex="-1"><code>doctor</code> <a class="header-anchor" href="#doctor" aria-label="Permalink to &quot;`doctor`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness doctor [--full]</span></span></code></pre></div><p>Checks this machine&#39;s setup and changes nothing. It prints one line per check: <code>PASS</code>, <code>WARN</code>, <code>FAIL</code> or <code>SKIP</code>, the name of the check and a detail. A <code>FAIL</code> line also names the section of the setup page that fixes it. The checks are, in this order: the machine; the tools of <a href="./dependencies">dependencies.md</a>, each with its minimum version; the profile; the dry run of <code>install</code> and its warnings; and the jobs (Kaimon, the update job, the autocommit job). Where the profile&#39;s <code>[setup]</code> does not choose <code>opencode</code>, the OpenCode directory check is a <code>SKIP</code>, and without the <code>julia</code> component so are the Julia packages. A layer of a frontend that <code>[setup]</code> does not choose and that is still on disk is a <code>WARN</code> that names <code>[setup]</code> and the frontend, and so is such a frontend whose plan refuses, with the refusal; <code>doctor</code> removes nothing.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--full</code></td><td style="text-align:left;">also run <code>harness test</code> and <code>julia -e &#39;using Revise&#39;</code>, which take minutes</td></tr></tbody></table><p><strong>Exit status:</strong> 1 when a check fails, else 0. A <code>WARN</code> or a <code>SKIP</code> does not count.</p><p><strong>Where to run it:</strong> in a plain terminal. In a session, the sandbox refuses some commands, and those checks are <code>SKIP</code> with the reason.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --full</span></span></code></pre></div><h3 id="trust" tabindex="-1"><code>trust</code> <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;`trust`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness trust [--apply]</span></span></code></pre></div><p>Marks the research root and every git repository below it as trusted in Claude Code&#39;s <code>~/.claude.json</code>, so that Claude Code shows no trust dialog. The dry run lists each untrusted root.</p><p><strong>Exit status:</strong> 0 when every root is trusted, or after <code>--apply</code>; 1 when the dry run finds an untrusted root; 2 when <code>~/.claude.json</code> cannot be read or is not a JSON object.</p><p><strong>Where to run it:</strong> in your own terminal. A session cannot read <code>~/.claude.json</code>. Run it again after <code>clone</code>: a new clone is not trusted.</p><h3 id="dotfiles-kit" tabindex="-1"><code>dotfiles-kit</code> <a class="header-anchor" href="#dotfiles-kit" aria-label="Permalink to &quot;`dotfiles-kit`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness dotfiles-kit [--apply] DEST</span></span></code></pre></div><p>Compares the chezmoi source <code>DEST</code> with the dotfiles kit of the harness, <code>examples/dotfiles/</code>. The file <code>examples/dotfiles/kit.toml</code> names each file of the kit and its class. A <em>code</em> file stays identical to the kit, so the dry run lists each code file that is missing from <code>DEST</code>, or differs in its bytes or in its execute bit. A <em>seed</em> file belongs to <code>DEST</code> once it is there, so the dry run lists each seed file that is missing, and <code>--apply</code> never writes a seed file that exists. A file of <code>DEST</code> that <code>kit.toml</code> does not name is not listed and not changed.</p><p><code>DEST</code> is a clone of your dotfiles repository. <code>dotfiles-kit</code> refuses the source that chezmoi applies, <code>~/.local/share/chezmoi</code>, and each directory below it, under any name of the same directory: a symbolic link, <code>..</code>, a case variant or a firmlink. A change of the applied source goes through a branch and a merge request. Every file that <code>dotfiles-kit</code> lists or writes stays inside <code>DEST</code>: when the directory of a file of <code>kit.toml</code> links out of <code>DEST</code>, the dry run and <code>--apply</code> stop before the first write and name the file. A symbolic link at a code file&#39;s own path is replaced by the file; anything else there that is not a regular file, such as a directory or a FIFO, stops <code>--apply</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">copy the listed files; without it, print the list</td></tr></tbody></table><p><strong>Exit status:</strong> 0 when nothing would change, or after <code>--apply</code>; 1 when the dry run lists a file; 2 when <code>DEST</code> is not a directory or is the applied source, when <code>kit.toml</code> cannot be read or names a file that the harness lacks or a class other than <code>code</code> and <code>seed</code>, when the directory of a file resolves outside <code>DEST</code>, when a code file of <code>DEST</code> cannot be read, and when a file cannot be written.</p><p><strong>Where to run it:</strong> where you can write <code>DEST</code>. Commit the change on a branch of the clone. <a href="./dotfiles-command#start-a-private-copy">The <code>dotfiles</code> command</a> gives the steps of a private copy, and the scripts that the kit installs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotfiles-kit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/src/dotfiles</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # the list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotfiles-kit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/src/dotfiles</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # copy</span></span></code></pre></div><h2 id="the-repositories-of-the-research-tree" tabindex="-1">The repositories of the research tree <a class="header-anchor" href="#the-repositories-of-the-research-tree" aria-label="Permalink to &quot;The repositories of the research tree&quot;">​</a></h2><p>These subcommands find the research tree at <code>$RESEARCH_ROOT</code>, or <code>~/Research</code> if it is not set. <a href="./research-tree#clone-sync-and-trust">The research tree</a> shows them in the order of a working day.</p><h3 id="the-repository-table" tabindex="-1">The repository table <a class="header-anchor" href="#the-repository-table" aria-label="Permalink to &quot;The repository table&quot;">​</a></h3><p><code>clone</code> and <code>repos</code> read the repository table: <code>$RESEARCH_HARNESS_REPOSITORIES</code>, or <code>repositories.toml</code> beside the profile if that is not set. It names each repository of the tree and its clone URL:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A fixed repository: its directory is the key in title case, ~/Research/Knowledge.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">knowledge = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://git.example.org/example/knowledge.git&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A group: its directory is the table&#39;s name in title case, and each key a directory there.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">packages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Example = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/example/Example.jl.git&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">papers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A Paper Title&quot; = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://git.example.org/example/papers/a-paper.git&quot;</span></span></code></pre></div><p>The fixed repositories are <code>knowledge</code>, <code>environment</code>, <code>tasks</code> and <code>library</code>. The groups are <code>packages</code>, <code>experiments</code>, <code>papers</code>, <code>books</code>, <code>talks</code> and <code>projects</code>. Another key is an error, and so is a directory name that holds a <code>/</code> or starts with <code>.</code>. <code>examples/repositories.toml</code> shows a whole table.</p><p>The table is optional. Without it, <code>repos</code> takes each git repository that it finds directly below the group directories, and each fixed repository that exists; <code>clone</code> stops. Directory names compare in Unicode NFC, so a name that the file system stores decomposed matches the table.</p><h3 id="selections" tabindex="-1">Selections <a class="header-anchor" href="#selections" aria-label="Permalink to &quot;Selections&quot;">​</a></h3><p><code>clone</code> and each action of <code>repos</code> take zero or more selections: a group (<code>packages</code>) or a fixed repository (<code>knowledge</code>), in any case. Without a selection, <code>clone</code>, <code>repos status</code> and <code>repos pull</code> take every group and every fixed repository, and <code>repos push</code> and <code>repos sync</code> take <code>packages</code> and <code>experiments</code>. An unknown selection exits 2 and names the valid ones.</p><h3 id="clone" tabindex="-1"><code>clone</code> <a class="header-anchor" href="#clone" aria-label="Permalink to &quot;`clone`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness clone [SELECTION ...] [--apply]</span></span></code></pre></div><p>Clones each repository of the table that has no directory yet. A directory that exists and is a clone of its URL is skipped. Two URLs are the same when they agree without a trailing <code>/</code> and <code>.git</code>. A directory that exists and is not a clone of its URL is in the way: the subcommand names it and stops before the first clone, and nothing is cloned.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SELECTION</code></td><td style="text-align:left;">a group or a fixed repository; none means all</td></tr><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">clone; without it, list the clones</td></tr></tbody></table><p><strong>Exit status:</strong> 0 when nothing is to clone, or after <code>--apply</code>; 1 when the dry run lists a clone; 2 when there is no table, the table is wrong, a directory is in the way, or a clone fails.</p><p><strong>Where to run it:</strong> in your own terminal: a clone needs the network and your credentials. A new clone has no git hooks and no workspace trust. After <code>--apply</code>, the subcommand names the three runs that give them.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # list what a new machine still lacks</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # clone it all</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> papers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # clone the papers only</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> githooks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # then the hooks,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wiki-lint-hook</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # and the workspace trust</span></span></code></pre></div><h3 id="repos-status" tabindex="-1"><code>repos status</code> <a class="header-anchor" href="#repos-status" aria-label="Permalink to &quot;`repos status`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness repos status [SELECTION ...] [--no-fetch] [--no-prs]</span></span></code></pre></div><p>Fetches every repository that has an origin, eight at a time, then prints one line for each repository: the branch, the commits ahead of and behind its upstream, the number of changed tracked files, and the numbers of the open pull requests. It asks <code>gh</code> for a repository on github.com, and <code>glab</code> for a repository on any other host. A <code>?</code> means that the host could not be asked; a <code>-</code> means no open pull request. A line also names:</p><ul><li><code>MISSING</code>: a repository of the table that is not cloned;</li><li><code>not in the table</code>: a git repository in a group directory that the table does not list;</li><li><code>no origin</code> and <code>no upstream</code>;</li><li><code>origin … is not the table&#39;s …</code>: a clone whose origin differs from the table;</li><li><code>fetch failed</code>, with the last line of git&#39;s error.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SELECTION</code></td><td style="text-align:left;">a group or a fixed repository; none means all</td></tr><tr><td style="text-align:left;"><code>--no-fetch</code></td><td style="text-align:left;">read the remote-tracking refs as the last fetch left them</td></tr><tr><td style="text-align:left;"><code>--no-prs</code></td><td style="text-align:left;">ask no host for pull requests</td></tr></tbody></table><p><strong>Exit status:</strong> 0; 2 when the table is wrong or a selection is unknown. The report itself never makes it exit 1.</p><p><strong>Where to run it:</strong> anywhere. In a session&#39;s sandbox, the fetches and the pull-request queries can fail; <code>--no-fetch --no-prs</code> then reports from the local state.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-prs</span></span></code></pre></div><h3 id="repos-pull" tabindex="-1"><code>repos pull</code> <a class="header-anchor" href="#repos-pull" aria-label="Permalink to &quot;`repos pull`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness repos pull [SELECTION ...] [--apply]</span></span></code></pre></div><p>Fetches, then fast-forwards each branch that is behind its upstream, with <code>git merge --ff-only</code>. It skips a branch with no upstream, a branch that has diverged from its upstream, and a branch whose incoming commits change a file with local changes. A local change to any other file stays as it is. The dry run fetches too: a fetch changes no working tree.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SELECTION</code></td><td style="text-align:left;">a group or a fixed repository; none means all</td></tr><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">fast-forward; without it, list the branches that would move</td></tr></tbody></table><p><strong>Exit status:</strong> 0 when nothing is behind, or after <code>--apply</code>; 1 when the dry run lists a branch; 2 when a merge fails.</p><p><strong>Where to run it:</strong> in your own terminal, which can reach the network.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><h3 id="repos-push" tabindex="-1"><code>repos push</code> <a class="header-anchor" href="#repos-push" aria-label="Permalink to &quot;`repos push`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness repos push [SELECTION ...] [--apply] [--no-verify] [--include-topic-branches]</span></span></code></pre></div><p>Fetches, then pushes each branch that is ahead of its upstream, one repository at a time. It checks each push against the remote ref, as <code>git ls-remote</code> reports it, not by the exit status of <code>git push</code>. It skips a branch with no upstream, and a branch that is also behind its upstream: pull or rebase it first. It skips a branch that is not the default branch, because a commit on a topic branch does not reach the required checks. The dry run names up to three <code>.jl</code> files of each push.</p><p>The pushes run in sequence, never in parallel. The pre-push hook of a package runs its full test suite, and two suites that load the same package with different settings invalidate each other&#39;s precompiled files.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SELECTION</code></td><td style="text-align:left;">a group or a fixed repository; none means <code>packages</code> and <code>experiments</code></td></tr><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">push; without it, list the pushes</td></tr><tr><td style="text-align:left;"><code>--no-verify</code>, <code>--skip-hooks</code></td><td style="text-align:left;">push with <code>git push --no-verify</code>: the pre-push hook does not run</td></tr><tr><td style="text-align:left;"><code>--include-topic-branches</code></td><td style="text-align:left;">also push a branch that is not the default branch</td></tr></tbody></table><p>Use <code>--no-verify</code> only for a push that touches no Julia source and no <code>[compat]</code> entry, such as a workflow, a README or a changelog. CI runs on the push anyway.</p><p><strong>Exit status:</strong> 0 when nothing is ahead, or after <code>--apply</code>; 1 when the dry run lists a push; 2 when a push fails. A failed push prints the last lines of git&#39;s output.</p><p><strong>Where to run it:</strong> in your own terminal, and expect it to take hours. A pre-push suite takes a few minutes in most packages and 10 to 30 minutes in the large ones, and prints nothing while it runs. A tool call of a session stops after ten minutes. Stopping a push in the middle of its suite leaves a Julia process behind; stop that process too.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # the plan</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # push, with each pre-push suite</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-verify</span></span></code></pre></div><h3 id="repos-sync" tabindex="-1"><code>repos sync</code> <a class="header-anchor" href="#repos-sync" aria-label="Permalink to &quot;`repos sync`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness repos sync [SELECTION ...] [--apply] [--no-verify] [--include-topic-branches]</span></span></code></pre></div><p>Runs <code>repos pull</code>, then <code>repos push</code>, on the same selection, with the same options. Without a selection it takes <code>packages</code> and <code>experiments</code>.</p><p><strong>Exit status:</strong> as <code>repos pull</code> and <code>repos push</code>: 1 when the dry run has something to pull or to push; 2 when a merge or a push fails.</p><p><strong>Where to run it:</strong> in your own terminal, as <code>repos push</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><h3 id="githooks" tabindex="-1"><code>githooks</code> <a class="header-anchor" href="#githooks" aria-label="Permalink to &quot;`githooks`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness githooks [--apply]</span></span></code></pre></div><p>Copies <code>githooks/pre-commit</code>, <code>githooks/pre-commit.jl</code>, <code>githooks/pre-push</code>, <code>githooks/pre-push.jl</code> and <code>scripts/test-layout.jl</code> into <code>.githooks/</code> of each git repository below <code>Packages/</code> and <code>Experiments/</code>, and sets <code>core.hooksPath</code> to <code>.githooks</code>. The copies are tracked files of each repository: read the diff, then commit each file by name. <code>core.hooksPath</code> is local configuration, so a new clone needs this subcommand again.</p><p><strong>Exit status:</strong> 0 when every copy is current, or after <code>--apply</code>; 1 when the dry run has a change; 2 when <code>core.hooksPath</code> cannot be set. The subcommand then prints the command for each repository.</p><p><strong>Where to run it:</strong> in your own terminal. A session cannot write <code>.git/config</code>.</p><h3 id="wiki-lint" tabindex="-1"><code>wiki-lint</code> <a class="header-anchor" href="#wiki-lint" aria-label="Permalink to &quot;`wiki-lint`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness wiki-lint [TREE ...] [--strict] [--quiet]</span></span></code></pre></div><p>Checks the structure of the Markdown in the prose repositories of the research tree: the vaults <code>Knowledge</code> and <code>Environment</code>, and the reference trees <code>Tasks</code> and <code>Library</code>, or the trees that <code>TREE</code> names. It finds text that a later change of the tree made false, for example a broken link, a path that does not exist, or a line citation past the end of its file. A vault gets every check. A reference tree gets the checks of paths and line citations; <code>Tasks</code> gets the schema of the task board too. The lint skips each <code>CHANGELOG.md</code>. It reads only the working tree: no model, no index, no network.</p><p>A frontmatter is YAML. In the vaults and in <code>Tasks</code>, a block that does not parse is an ERROR on the line that PyYAML names, and so is a key that a block repeats. A key or a value that YAML 1.1 converts, an item of a list included, such as <code>draft: no</code> (false) or <code>mode: 0755</code> (493), is a WARN that names the key and the value; quote it to keep the text. The date of <code>verified:</code> is text of the form <code>YYYY-MM-DD</code>.</p><p>It prints one line per finding, <code>&lt;SEVERITY&gt; [&lt;check&gt;] &lt;file&gt;[:&lt;line&gt;] — &lt;message&gt;</code>, then the counts by check and the totals. <code>--quiet</code> prints no WARN line, and the ERROR lines only when there is one. The hook <code>pre-commit-wiki</code> (see <a href="./components/githooks">Git hooks and workflows</a>) runs it with <code>--quiet</code> before each commit in a prose repository.</p><p><strong>Exit status:</strong> 0 when there is no ERROR, and with <code>--strict</code> no WARN; 1 on a finding at the failing level; 2 for a <code>TREE</code> that is no directory, and when the Python environment lacks PyYAML.</p><p><strong>Where to run it:</strong> anywhere; it changes nothing.</p><h3 id="wiki-lint-hook" tabindex="-1"><code>wiki-lint-hook</code> <a class="header-anchor" href="#wiki-lint-hook" aria-label="Permalink to &quot;`wiki-lint-hook`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness wiki-lint-hook [--apply]</span></span></code></pre></div><p>Copies <code>githooks/pre-commit-wiki</code> as <code>.githooks/pre-commit</code> into each prose repository of the research tree (<code>Knowledge</code>, <code>Environment</code>, <code>Tasks</code>, <code>Library</code>), and sets <code>core.hooksPath</code>. It skips a name that is not a git repository.</p><p><strong>Exit status and where to run it:</strong> as <code>githooks</code>.</p><h3 id="workflows" tabindex="-1"><code>workflows</code> <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;`workflows`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness workflows [--apply]</span></span></code></pre></div><p>Copies the canonical files of <code>githooks/workflows/</code> into each package and experiment that has a <code>Project.toml</code>: <code>CI.yml</code>, <code>dependabot.yml</code> and <code>codecov.yml</code> into each, <code>TagBot.yml</code> into each package, and <code>Documenter.yml</code> where a tracked <code>docs/make.jl</code> exists. A repository that the profile keys <code>docs_exceptions</code> or <code>docs_additions</code> name keeps its own documentation workflow. It deletes the retired <code>CompatHelper.yml</code>.</p><p><strong>Exit status:</strong> 0 when every file is current, or after <code>--apply</code>; 1 when the dry run has a change; 2 when a template is missing.</p><p><strong>Where to run it:</strong> anywhere; it writes tracked files only. Commit each file by name.</p><h3 id="ci-protection" tabindex="-1"><code>ci-protection</code> <a class="header-anchor" href="#ci-protection" aria-label="Permalink to &quot;`ci-protection`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness ci-protection [--apply] [--remove-classic]</span></span></code></pre></div><p>Protects the default branch of each repository that has a <code>CI.yml</code> with a GitHub ruleset named <code>main</code>, which requires the status checks of the canonical <code>CI.yml</code>. It also turns on auto-merge and the deletion of merged branches. It reads the current state first and writes only what differs. It refuses to run unless <code>verify-workflows.jl</code> passes: a required check that never reports leaves every pull request pending.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">write through <code>gh api</code>; without it, print what would change</td></tr><tr><td style="text-align:left;"><code>--remove-classic</code></td><td style="text-align:left;">delete classic branch protection where the ruleset passes every check</td></tr></tbody></table><p>Run the ruleset first and <code>--remove-classic</code> afterwards, so that a branch is never left unprotected.</p><p><strong>Exit status:</strong> 0 when nothing would change, or after <code>--apply</code>; 1 when the dry run has a change; 2 when the workflows are not canonical or a call fails.</p><p><strong>Where to run it:</strong> in your own terminal. In a session&#39;s sandbox only the first <code>gh</code> call of a process succeeds.</p><h3 id="format" tabindex="-1"><code>format</code> <a class="header-anchor" href="#format" aria-label="Permalink to &quot;`format`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness format [--apply]</span></span></code></pre></div><p>Runs JuliaFormatter over the tracked <code>.jl</code> files of the repositories below <code>Packages/</code> and <code>Experiments/</code>. It skips a repository that has no <code>.JuliaFormatter.toml</code>, and each file on which JuliaFormatter crashes. The dry run counts the files that would change.</p><p><strong>Exit status:</strong> 0 when no file would change, or after <code>--apply</code>; 1 when the dry run counts a file; 2 on a failure.</p><p><strong>Files:</strong> the marker, the skip list and the log go to <code>$FMT_OUT</code>, or <code>$TMPDIR</code> if that is not set. The skip list that remains names the files that JuliaFormatter cannot format.</p><p><strong>Where to run it:</strong> in your own terminal; it runs Julia over the whole tree.</p><h2 id="the-profile" tabindex="-1">The profile <a class="header-anchor" href="#the-profile" aria-label="Permalink to &quot;The profile&quot;">​</a></h2><h3 id="render" tabindex="-1"><code>render</code> <a class="header-anchor" href="#render" aria-label="Permalink to &quot;`render`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness render TEMPLATE</span></span></code></pre></div><p>Prints <code>TEMPLATE</code> with each placeholder <code>{key}</code> replaced by its profile value. <a href="./profile">profile.md</a> describes the placeholders.</p><p><strong>Exit status:</strong> 0; 2 when a placeholder has no profile value.</p><h3 id="get" tabindex="-1"><code>get</code> <a class="header-anchor" href="#get" aria-label="Permalink to &quot;`get`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness get KEY</span></span></code></pre></div><p>Prints the profile value of <code>KEY</code>, one line per item of a list, and <code>develop</code> of <code>[setup]</code> as <code>true</code> or <code>false</code>. A path that starts with <code>~</code> is printed with the home directory.</p><p><strong>Exit status:</strong> 0; 2 when the profile does not load or has no <code>KEY</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository_roots</span></span></code></pre></div><h3 id="leaks" tabindex="-1"><code>leaks</code> <a class="header-anchor" href="#leaks" aria-label="Permalink to &quot;`leaks`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness leaks [--commits FILE]</span></span></code></pre></div><p>Searches the tracked files of the harness repository, and the templates rendered with the dummy profile, for the private strings of the profile&#39;s <code>leak</code> list and for the names of the research tree. It matches a whole word. The pre-push hook of the harness runs it.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--commits FILE</code></td><td style="text-align:left;">also search the paths and lines that each commit of <code>FILE</code> adds, and its message; one SHA per line</td></tr></tbody></table><p><strong>Exit status:</strong> 0 with no hit, 1 on a hit, 2 when the profile does not load.</p><h2 id="settings-and-permissions" tabindex="-1">Settings and permissions <a class="header-anchor" href="#settings-and-permissions" aria-label="Permalink to &quot;Settings and permissions&quot;">​</a></h2><h3 id="settings" tabindex="-1"><code>settings</code> <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;`settings`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness settings surface [--settings F] [--days N] [--head N]</span></span>\n<span class="line"><span>harness settings compare OLD NEW [--days N]</span></span>\n<span class="line"><span>harness settings twins [--settings F] [--list allow|ask|deny]</span></span>\n<span class="line"><span>harness settings selftest</span></span></code></pre></div><p>Measures and checks the Claude Code settings against the Bash commands of the recent session transcripts in <code>~/.claude/projects/</code>. Each subcommand of <code>settings</code> is read-only.</p><table tabindex="0"><thead><tr><th style="text-align:left;">subcommand</th><th style="text-align:left;">does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>surface</code></td><td style="text-align:left;">counts the segments of the recent Bash commands that reach a permission prompt under one settings file, by leading word. <code>--days N</code> reads the last <code>N</code> days (default 5); <code>--head N</code> prints the <code>N</code> most frequent prompting segments</td></tr><tr><td style="text-align:left;"><code>compare</code></td><td style="text-align:left;">the same count for two settings files, side by side, with the difference</td></tr><tr><td style="text-align:left;"><code>twins</code></td><td style="text-align:left;">prints the <code>git -C * &lt;sub&gt;</code> twin of each plain <code>git</code> rule: <code>Bash(git status *)</code> does not match <code>git -C /path status</code></td></tr><tr><td style="text-align:left;"><code>selftest</code></td><td style="text-align:left;">checks the matcher against the recorded cases of Claude Code; run it after a Claude Code update. Exits 1 when a case fails</td></tr></tbody></table><p><code>--settings F</code> defaults to <code>~/.claude/settings.json</code>.</p><p><strong>Exit status:</strong> 0; 1 for a failed <code>selftest</code> case; 2 when a settings file is missing, cannot be read, or is not a JSON object.</p><h3 id="permissions" tabindex="-1"><code>permissions</code> <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;`permissions`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness permissions [--apply]</span></span></code></pre></div><p>Regenerates the permission block of <code>adapters/opencode/opencode.jsonc</code> and <code>adapters/opencode/plugins/guard-paths.json</code> in the harness repository from the <code>deny</code> and <code>ask</code> rules of the settings template. The dry run prints the report and the diff.</p><p><strong>Exit status:</strong> 0 when the files are current, or after <code>--apply</code>; 1 when the dry run has a diff.</p><p><strong>Where to run it:</strong> in the harness checkout; commit the two files with the change of the template.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><h3 id="test" tabindex="-1"><code>test</code> <a class="header-anchor" href="#test" aria-label="Permalink to &quot;`test`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness test [NAME ...] [--changed BASE] [--list] [--jobs N] [--log FILE]</span></span></code></pre></div><p>Runs the harness&#39;s own test cases as parts, each in a process of its own: the cases of each module and adapter, the groups of the hook probe and of <code>doctor</code>, and the contract sweep. The sweep runs the dry run of each subcommand on a fixture home directory and checks the contract above. It prints each part&#39;s lines and, last, <code>&lt;n&gt; cases, &lt;w&gt; wrong</code>. <a href="./development#tests">development.md</a> describes the parts and the selection.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NAME ...</code></td><td style="text-align:left;">run these parts, with <code>docs</code> and <code>sweep</code></td></tr><tr><td style="text-align:left;"><code>--changed BASE</code></td><td style="text-align:left;">run the parts that own a path of <code>git diff --name-status BASE...HEAD</code>, with <code>docs</code> and <code>sweep</code>; a path that no part owns selects every part</td></tr><tr><td style="text-align:left;"><code>--list</code></td><td style="text-align:left;">print the selected part names, one per line, and run nothing</td></tr><tr><td style="text-align:left;"><code>--jobs N</code></td><td style="text-align:left;">run at most N parts at once; the default is half the CPUs</td></tr><tr><td style="text-align:left;"><code>--log FILE</code></td><td style="text-align:left;">write every line and a line <code>part &lt;name&gt;: &lt;n&gt; cases, &lt;w&gt; wrong</code> per part to <code>FILE</code>; print only the <code>BAD</code> lines and the summary</td></tr></tbody></table><p>At most two runs share a machine; a third waits for one of them to end.</p><p><strong>Exit status:</strong> 0 when every case passes, 1 when a case fails, 2 on a usage error: an unknown part, part names together with <code>--changed</code>, an empty <code>BASE</code> or one that git cannot resolve, <code>--jobs</code> below 1, a <code>--log</code> file whose directory does not exist, or a directory of the slot files that cannot be made or written.</p><h3 id="mutate" tabindex="-1"><code>mutate</code> <a class="header-anchor" href="#mutate" aria-label="Permalink to &quot;`mutate`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness mutate SPEC</span></span></code></pre></div><p>Runs named mutants of the Python code of the harness. <code>SPEC</code> is a TOML file with one table per mutant, in the order in which they run:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MU1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lib/harness/changelog.py&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a path relative to the harness checkout</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">anchor = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DIRECTORY = &quot;changelog.d&quot;&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # a text on exactly one line of file</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">old = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;HEADING = &quot;## Unreleased&quot;&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # a text that occurs exactly once after the end of that line</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">new = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;HEADING = &quot;## Released&quot;&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # the text that replaces it</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tests = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;changelog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the parts of harness test that should kill the mutant</span></span></code></pre></div><p>The anchor tells two equal texts apart without a line number. <code>mutate</code> copies the checkout into a temporary directory: its tracked files and its untracked files that git does not ignore, with their working-tree bytes, as a git repository, because the parts <code>docs</code> and <code>sweep</code> read <code>git ls-files</code>. It writes nothing into the checkout or its <code>.git</code>, and removes the copy after the run, also after an error or an interrupt. The copy first runs <code>harness test</code> with the parts of every mutant, unmutated. Then each mutant is applied alone to the copy, <code>harness test</code> runs with its parts, and the file is reverted. It prints one line per mutant and, last, <code>&lt;n&gt; mutants, &lt;k&gt; killed, &lt;s&gt; survived, &lt;i&gt; invalid</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">line</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&lt;name&gt; killed: &lt;line&gt;</code></td><td style="text-align:left;">the first <code>BAD</code> line of the run. A run that fails with no <code>BAD</code> line, such as a crash at import, gives <code>exit &lt;status&gt; with no BAD line: &lt;its last line&gt;</code></td></tr><tr><td style="text-align:left;"><code>&lt;name&gt; killed (timeout): &lt;line&gt;</code></td><td style="text-align:left;">the first <code>BAD</code> line is that of a part stopped after its timeout of 300 s</td></tr><tr><td style="text-align:left;"><code>&lt;name&gt; SURVIVED</code></td><td style="text-align:left;">every case of the mutant&#39;s parts passes</td></tr><tr><td style="text-align:left;"><code>&lt;name&gt; invalid: &lt;error&gt;</code></td><td style="text-align:left;"><code>ast.parse</code> refuses the mutated file; no test runs</td></tr></tbody></table><p>A line of <code>file</code> ends at a newline only; a form feed does not end it. <code>mutate</code> stops before any mutant runs, and the message names the mutant, when a table lacks one of the five keys, has another key, or has a value of the wrong type; <code>old</code> is empty; <code>file</code> is not a file of the copy or is not UTF-8; <code>anchor</code> is on no line or on more than one; <code>old</code> does not occur exactly once after the anchor&#39;s line; <code>tests</code> is empty, or names a part that <code>harness test --list</code> does not name. It also stops when the spec cannot be read or holds no mutant, with a message that names the spec; when <code>harness test --list</code> of the copy fails, with its exit status; and when the unmutated copy fails the parts of the spec, with the first <code>BAD</code> line.</p><p><strong>Exit status:</strong> 0 when every mutant is killed, 1 when a mutant survives or is invalid, 2 when it stops.</p><p><strong>Where to run it:</strong> in the harness checkout. It runs <code>harness test</code>, so it takes as long as the parts that it names, once for the unmutated copy and once per valid mutant.</p><h3 id="changelog" tabindex="-1"><code>changelog</code> <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;`changelog`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness changelog [--apply | --check BASE]</span></span></code></pre></div><p>Joins the changelog fragments of the harness checkout into its <code>CHANGELOG.md</code>. A fragment is a file <code>changelog.d/*.md</code> other than <code>README.md</code>, and holds the entry of one branch; <code>changelog.d/README.md</code> gives its name and its form. The dry run prints the <code>## Unreleased</code> block that the fragments make: each fragment&#39;s text, with a final newline added where it lacks one, separated by one blank line. The newest fragment comes first, by the committer date of the commit that added it; a fragment that no commit holds comes before them, and fragments of the same date go by file name.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">put the block at the top of the <code>## Unreleased</code> section of <code>CHANGELOG.md</code>, above its entries, and delete the fragments. Without that heading, it inserts <code>## Unreleased</code> above the first <code>## </code> heading, or at the end</td></tr><tr><td style="text-align:left;"><code>--check BASE</code></td><td style="text-align:left;">read <code>git diff --name-status BASE...HEAD</code>, and fail when the branch changes a path below <code>lib/</code>, <code>hooks/</code>, <code>adapters/</code>, <code>bin/</code>, <code>scripts/</code>, <code>githooks/</code>, <code>agents/</code>, <code>skills/</code> or <code>rules/</code> and adds no fragment</td></tr></tbody></table><p>A fragment that is empty, holds only whitespace, holds a carriage return or is not UTF-8 stops the dry run and <code>--apply</code>; the message names it, and no file changes.</p><p><strong>Exit status:</strong> without <code>--check</code>, 0 when there is no fragment, or after <code>--apply</code>; 1 when the dry run prints a block; 2 on a bad fragment or a failure. With <code>--check</code>, 0 when a fragment is added or no code changes; 1 when code changes without a fragment, and the output names the first such path; 2 when <code>BASE</code> is empty or git cannot resolve it.</p><p><strong>Where to run it:</strong> in the harness checkout. CI runs <code>--check</code> on each pull request.</p><h3 id="skill-triggers" tabindex="-1"><code>skill-triggers</code> <a class="header-anchor" href="#skill-triggers" aria-label="Permalink to &quot;`skill-triggers`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harness skill-triggers [--skill NAME ...] [--apply --model ALIAS]</span></span></code></pre></div><p>Tests whether each skill loads on the queries of <code>tests/skill-triggers/&lt;skill&gt;.toml</code>, and stays unloaded on its near misses. The dry run prints the number of queries per skill and the number of sessions that <code>--apply</code> starts.</p><table tabindex="0"><thead><tr><th style="text-align:left;">option</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--skill NAME</code></td><td style="text-align:left;">only the query file of this skill; can repeat</td></tr><tr><td style="text-align:left;"><code>--apply</code></td><td style="text-align:left;">run the sessions and write the report</td></tr><tr><td style="text-align:left;"><code>--model ALIAS</code></td><td style="text-align:left;">the model of the sessions; <code>--apply</code> needs it</td></tr></tbody></table><p><code>--apply</code> runs one <code>claude -p</code> session of 3 turns per query, <strong>at your cost</strong>, and writes the report to <code>$RESEARCH_ROOT/.scratch/skill-triggers/&lt;date&gt;-&lt;model&gt;.md</code>.</p><p><strong>Exit status:</strong> the dry run exits 1; <code>--apply</code> exits 0 when every skill passes, else 1.</p><p><strong>Where to run it:</strong> in your own terminal.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">variable</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RESEARCH_ROOT</code></td><td style="text-align:left;">the research tree; <code>~/Research</code> if it is not set</td></tr><tr><td style="text-align:left;"><code>RESEARCH_HARNESS_PROFILE</code></td><td style="text-align:left;">the profile, when <code>--profile</code> is not given</td></tr><tr><td style="text-align:left;"><code>RESEARCH_HARNESS_MODELS</code></td><td style="text-align:left;">the model tables, when <code>--models</code> is not given</td></tr><tr><td style="text-align:left;"><code>RESEARCH_HARNESS_REPOSITORIES</code></td><td style="text-align:left;">the repository table of <code>clone</code> and <code>repos</code></td></tr><tr><td style="text-align:left;"><code>RESEARCH_HARNESS_JULIA</code></td><td style="text-align:left;">the Julia environment of the scripts; <code>~/.local/share/research-harness/julia/</code> if it is not set</td></tr><tr><td style="text-align:left;"><code>RESEARCH_HARNESS_PYTHON</code></td><td style="text-align:left;">the Python environment of the harness; <code>~/.local/share/research-harness/python/</code> if it is not set</td></tr><tr><td style="text-align:left;"><code>OPENCODE_CONFIG_DIR</code></td><td style="text-align:left;">OpenCode&#39;s configuration directory; <code>~/.config/opencode</code> if it is not set</td></tr><tr><td style="text-align:left;"><code>PI_CODING_AGENT_DIR</code></td><td style="text-align:left;">oh-my-pi&#39;s agent directory; <code>~/.omp/agent</code> if it is not set</td></tr><tr><td style="text-align:left;"><code>FMT_OUT</code></td><td style="text-align:left;">the directory of the marker, the skip list and the log of <code>format</code></td></tr><tr><td style="text-align:left;"><code>SANDBOX_RUNTIME</code></td><td style="text-align:left;">set by the Claude Code sandbox; <code>doctor</code> reports a refused check as <code>SKIP</code></td></tr></tbody></table><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">file</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>~/.config/research-harness/profile.toml</code></td><td style="text-align:left;">the private profile; <code>examples/profile.toml</code> shows every key</td></tr><tr><td style="text-align:left;"><code>models.toml</code> beside the profile</td><td style="text-align:left;">the model tables; <code>examples/models.toml</code></td></tr><tr><td style="text-align:left;"><code>providers.toml</code> beside the profile</td><td style="text-align:left;">the model providers of OpenCode and oh-my-pi; <code>examples/providers.toml</code></td></tr><tr><td style="text-align:left;"><code>network.toml</code> beside the profile</td><td style="text-align:left;">the overlay of the network lists of the settings; <code>examples/network.toml</code></td></tr><tr><td style="text-align:left;"><code>repositories.toml</code> beside the profile</td><td style="text-align:left;">the repository table; <code>examples/repositories.toml</code></td></tr><tr><td style="text-align:left;"><code>~/.claude/.harness-install.json</code></td><td style="text-align:left;">the stamp of the last <code>install --apply</code></td></tr><tr><td style="text-align:left;"><code>~/.claude.json</code></td><td style="text-align:left;">Claude Code&#39;s state, which <code>trust</code> writes</td></tr></tbody></table><h2 id="exit-status" tabindex="-1">Exit status <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">status</th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">nothing to do, the change is made, or the read-only subcommand finished</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">the dry run has work to do; a check (<code>doctor</code>, <code>leaks</code>, <code>test</code>, <code>mutate</code>, <code>settings selftest</code>, <code>skill-triggers</code>) failed</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">a usage error, a refusal or a failure, with one line on standard error</td></tr></tbody></table><h2 id="the-julia-environment" tabindex="-1">The Julia environment <a class="header-anchor" href="#the-julia-environment" aria-label="Permalink to &quot;The Julia environment&quot;">​</a></h2><p>The Julia scripts load their packages from <code>Project.toml</code>, which <code>harness install --apply</code> instantiates in <code>~/.local/share/research-harness/julia/</code>; no caller needs <code>--project</code>.</p>',210)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
